import SearchOutlined from '@mui/icons-material/SearchOutlined'
import { Box, IconButton, InputAdornment, Popover, TextField, ToggleButton, Tooltip } from '@mui/material'
import { useLexicalComposerContext } from '@lexical/react/LexicalComposerContext'
import { useCellValue } from '@mdxeditor/editor'
import { COMMAND_PRIORITY_HIGH, KEY_DOWN_COMMAND } from 'lexical'
import {
    useCallback,
    useEffect,
    useState,
    type ChangeEvent,
    type KeyboardEvent as ReactKeyboardEvent,
} from 'react'
import { useDialogError } from '../hooks/use_dialog_error'
import {
    getMarkdownSearchSeed,
    getMarkdownSearchSelectionEnd,
    selectMarkdownTextMatch,
} from './markdown_local_text_search'
import { OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND } from './markdown_local_text_search_command'
import { markdownLocalTextSearchConfig$ } from './markdown_local_text_search_config_cell'

function isOpenSearchShortcut(event: KeyboardEvent) {
    return event.ctrlKey && !event.altKey && !event.metaKey && event.key.toLowerCase() === 'f'
}

/** Editor-local search keyboard handling and popup. */
export function MarkdownLocalTextSearchPlugin() {
    const config = useCellValue(markdownLocalTextSearchConfig$)
    const [editor] = useLexicalComposerContext()
    const [activeCaseSensitive, setActiveCaseSensitive] = useState(false)
    const [activeTerm, setActiveTerm] = useState<string | null>(null)
    const [draftCaseSensitive, setDraftCaseSensitive] = useState(false)
    const [draftTerm, setDraftTerm] = useState('')
    const [open, setOpen] = useState(false)
    const [searchOrigin, setSearchOrigin] = useState(0)
    const rootElement = editor.getRootElement()
    const configError = config ? null : new Error('Cannot register Markdown local text search without configuration')
    useDialogError(configError, 'Local text search is unavailable')

    const closeSearch = useCallback(() => {
        setOpen(false)
    }, [])

    const openSearch = useCallback(() => {
        const selectedText = getMarkdownSearchSeed(editor)
        setSearchOrigin(getMarkdownSearchSelectionEnd(editor))
        if (selectedText) setDraftTerm(selectedText)
        setOpen(true)
        return true
    }, [editor])

    const selectNextMatch = useCallback(() => {
        if (!activeTerm) return
        const offset = getMarkdownSearchSelectionEnd(editor)
        selectMarkdownTextMatch(editor, activeTerm, offset, activeCaseSensitive)
    }, [activeCaseSensitive, activeTerm, editor])

    const submitSearch = useCallback(() => {
        if (!draftTerm) return
        setActiveTerm(draftTerm)
        setActiveCaseSensitive(draftCaseSensitive)
        selectMarkdownTextMatch(editor, draftTerm, searchOrigin, draftCaseSensitive)
    }, [draftCaseSensitive, draftTerm, editor, searchOrigin])

    const handleKeyDown = useCallback((event: KeyboardEvent) => {
        if (isOpenSearchShortcut(event)) {
            event.preventDefault()
            openSearch()
            return true
        }
        if (event.key !== 'F3') return false

        event.preventDefault()
        selectNextMatch()
        return true
    }, [openSearch, selectNextMatch])

    useEffect(() => {
        const unregisterOpen = editor.registerCommand(
            OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND,
            openSearch,
            COMMAND_PRIORITY_HIGH,
        )
        const unregisterKeyDown = editor.registerCommand(KEY_DOWN_COMMAND, handleKeyDown, COMMAND_PRIORITY_HIGH)

        return () => {
            unregisterOpen()
            unregisterKeyDown()
        }
    }, [editor, handleKeyDown, openSearch])

    const handleTermChange = (event: ChangeEvent<HTMLInputElement>) => {
        setDraftTerm(event.target.value)
    }

    const handleCaseToggle = () => {
        setDraftCaseSensitive((current) => !current)
    }

    const handleInputKeyDown = (event: ReactKeyboardEvent<HTMLInputElement>) => {
        if (event.key === 'Escape') {
            event.preventDefault()
            closeSearch()
            return
        }
        if (event.key === 'Enter') {
            event.preventDefault()
            submitSearch()
            return
        }
        if (event.key !== 'F3') return

        event.preventDefault()
        selectNextMatch()
    }

    return (
        <Popover
            anchorEl={rootElement}
            anchorOrigin={{ horizontal: 'right', vertical: 'top' }}
            anchorPosition={rootElement ? undefined : { left: 0, top: 0 }}
            anchorReference={rootElement ? 'anchorEl' : 'anchorPosition'}
            container={config?.overlayContainer ?? undefined}
            onClose={closeSearch}
            open={open}
            slotProps={{
                paper: {
                    sx: {
                        border: '1px solid',
                        borderColor: 'divider',
                        borderRadius: '14px',
                    },
                },
            }}
            transformOrigin={{ horizontal: 'right', vertical: 'top' }}
        >
            <Box sx={{ alignItems: 'center', display: 'flex', gap: 0.75, p: 1, width: 260 }}>
                <TextField
                    autoFocus
                    fullWidth
                    onChange={handleTermChange}
                    onKeyDown={handleInputKeyDown}
                    placeholder="Find text"
                    size="small"
                    slotProps={{
                        htmlInput: { 'aria-label': 'Find text' },
                        input: {
                            startAdornment: (
                                <InputAdornment position="start">
                                    <Tooltip title="Search">
                                        <IconButton aria-label="Search" edge="start" onClick={submitSearch} size="small">
                                            <SearchOutlined fontSize="small" />
                                        </IconButton>
                                    </Tooltip>
                                </InputAdornment>
                            ),
                        },
                    }}
                    value={draftTerm}
                />
                <Tooltip title="Match case">
                    <ToggleButton
                        aria-label="Match case"
                        onClick={handleCaseToggle}
                        selected={draftCaseSensitive}
                        size="small"
                        value="case-sensitive"
                    >
                        Aa
                    </ToggleButton>
                </Tooltip>
            </Box>
        </Popover>
    )
}

import {
    $createRangeSelection,
    $getRoot,
    $getSelection,
    $isElementNode,
    $isRangeSelection,
    $isTextNode,
    $setSelection,
    type LexicalEditor,
    type NodeKey,
    type PointType,
} from 'lexical'

export interface MarkdownTextMatch {
    end: number
    start: number
}

interface MarkdownTextSegment {
    end: number
    key: NodeKey
    start: number
}

interface MarkdownSearchDocument {
    segments: MarkdownTextSegment[]
    text: string
}

function createSearchDocument(): MarkdownSearchDocument {
    const root = $getRoot()
    const text = root.getTextContent()
    let nextOffset = 0
    const segments = root.getAllTextNodes().flatMap((node) => {
        const nodeText = node.getTextContent()
        if (!nodeText) return []

        const start = text.indexOf(nodeText, nextOffset)
        if (start < 0) throw new Error(`Markdown search could not map text node ${node.getKey()}`)
        const end = start + nodeText.length
        nextOffset = end

        return [{ end, key: node.getKey(), start }]
    })

    return { segments, text }
}

function normalizeSearchText(value: string, caseSensitive: boolean) {
    return caseSensitive ? value : value.toLocaleLowerCase()
}

/** Finds next match at or after offset, wrapping once to document start. */
export function findMarkdownTextMatch(
    text: string,
    term: string,
    offset: number,
    caseSensitive: boolean,
): MarkdownTextMatch | null {
    if (!term) return null

    const searchableText = normalizeSearchText(text, caseSensitive)
    const searchableTerm = normalizeSearchText(term, caseSensitive)
    const startOffset = Math.min(Math.max(offset, 0), text.length)
    const laterMatch = searchableText.indexOf(searchableTerm, startOffset)
    const start = laterMatch >= 0 ? laterMatch : searchableText.indexOf(searchableTerm)

    return start < 0 ? null : { end: start + term.length, start }
}

function pointTextOffset(point: PointType, document: MarkdownSearchDocument) {
    if (point.type === 'text') {
        const segment = document.segments.find(({ key }) => key === point.key)
        return segment ? segment.start + point.offset : 0
    }

    const pointNode = point.getNode()
    const nextChild = 'getChildAtIndex' in pointNode ? pointNode.getChildAtIndex(point.offset) : null
    const nextTextKey = $isTextNode(nextChild)
        ? nextChild.getKey()
        : $isElementNode(nextChild) ? nextChild.getAllTextNodes()[0]?.getKey() : undefined
    const nextSegment = document.segments.find(({ key }) => key === nextTextKey)
    if (nextSegment) return nextSegment.start

    const pointTextKeys = new Set($isElementNode(pointNode)
        ? pointNode.getAllTextNodes().map((node) => node.getKey())
        : [])
    const lastSegment = document.segments.findLast(({ key }) => pointTextKeys.has(key))
    return lastSegment?.end ?? 0
}

function currentSelectionEnd(document: MarkdownSearchDocument) {
    const selection = $getSelection()
    if (!$isRangeSelection(selection)) return 0

    const points = selection.getStartEndPoints()
    return points ? pointTextOffset(points[1], document) : 0
}

function matchPoints(match: MarkdownTextMatch, segments: MarkdownTextSegment[]) {
    const startSegment = segments.find(({ end, start }) => match.start >= start && match.start < end)
    const endSegment = segments.find(({ end, start }) => match.end > start && match.end <= end)
    if (!startSegment || !endSegment) return null

    return {
        anchor: { key: startSegment.key, offset: match.start - startSegment.start },
        focus: { key: endSegment.key, offset: match.end - endSegment.start },
    }
}

/** Reads current Lexical selection end as flattened visible-text offset. */
export function getMarkdownSearchSelectionEnd(editor: LexicalEditor) {
    return editor.getEditorState().read(() => currentSelectionEnd(createSearchDocument()))
}

/** Reads non-empty selected visible text without Markdown delimiters. */
export function getMarkdownSearchSeed(editor: LexicalEditor) {
    return editor.getEditorState().read(() => {
        const selection = $getSelection()
        return $isRangeSelection(selection) && !selection.isCollapsed() ? selection.getTextContent() : ''
    })
}

/** Selects one match without changing editor content or history. */
export function selectMarkdownTextMatch(
    editor: LexicalEditor,
    term: string,
    offset: number,
    caseSensitive: boolean,
) {
    let selectedKey: NodeKey | null = null
    let selectedMatch: MarkdownTextMatch | null = null

    editor.update(() => {
        const document = createSearchDocument()
        const match = findMarkdownTextMatch(document.text, term, offset, caseSensitive)
        if (!match) return

        const points = matchPoints(match, document.segments)
        if (!points) return

        const selection = $createRangeSelection()
        selection.anchor.set(points.anchor.key, points.anchor.offset, 'text')
        selection.focus.set(points.focus.key, points.focus.offset, 'text')
        $setSelection(selection)
        selectedKey = points.anchor.key
        selectedMatch = match
    }, {
        discrete: true,
        onUpdate: () => {
            if (selectedKey) editor.getElementByKey(selectedKey)?.scrollIntoView?.({ block: 'nearest' })
        },
    })

    return selectedMatch
}

import { createCommand } from 'lexical'

/** Opens local text search for the active Markdown editor. */
export const OPEN_MARKDOWN_LOCAL_TEXT_SEARCH_COMMAND = createCommand<void>()

import { addComposerChild$, realmPlugin } from '@mdxeditor/editor'
import {
    markdownLocalTextSearchConfig$,
    type MarkdownLocalTextSearchConfig,
} from './markdown_local_text_search_config_cell'
import { MarkdownLocalTextSearchPlugin } from './markdown_local_text_search_plugin'

/** Connects local visible-text search to an MDXEditor Lexical composer. */
export const markdownLocalTextSearchPlugin = realmPlugin<MarkdownLocalTextSearchConfig>({
    init(realm, params) {
        if (!params) throw new Error('Markdown local text-search plugin requires parameters')

        realm.register(markdownLocalTextSearchConfig$)
        realm.pub(markdownLocalTextSearchConfig$, params)
        realm.pub(addComposerChild$, MarkdownLocalTextSearchPlugin)
    },
    update(realm, params) {
        if (!params) throw new Error('Markdown local text-search plugin requires parameters')

        realm.pub(markdownLocalTextSearchConfig$, params)
    },
})

import { Cell } from '@mdxeditor/editor'

export interface MarkdownLocalTextSearchConfig {
    overlayContainer?: HTMLElement | null
}

export const markdownLocalTextSearchConfig$ = Cell<MarkdownLocalTextSearchConfig | null>(null)

import { cleanup, fireEvent, render, screen, waitFor } from '@testing-library/react'
import { afterEach, describe, expect, it, vi } from 'vitest'
import { AppThemeProvider } from '../../theme/theme_provider'
import type { CardOpenDocument } from '../../services/open_files_service'
import { MarkdownEditor } from './markdown_editor'
import { MarkdownDocumentHistoryStore } from './markdown_document_history_store'
import {
    MarkdownDataSourceBase,
    type MarkdownDataSource,
    type MarkdownDocumentTarget,
} from './markdown_data_source'

class SearchTestDataSource extends MarkdownDataSourceBase {
    readonly commit = vi.fn<MarkdownDataSource['commit']>(() => true)
    readonly edit = vi.fn()
    private readonly markdown: string
    private readonly target: MarkdownDocumentTarget

    constructor(markdown: string) {
        super()
        this.markdown = markdown
        const document = Object.assign(new EventTarget(), { kind: 'card' as const }) as CardOpenDocument
        this.target = { document }
        this.setActiveTarget('list-card', this.target)
    }

    getMarkdown(target: MarkdownDocumentTarget) {
        if (target !== this.target) throw new Error('Unknown search test document')
        return this.markdown
    }
}

interface SearchEditorOverrides {
    hideToolbar?: boolean
    localTextSearch?: boolean
    overlayContainer?: HTMLElement | null
    readOnly?: boolean
}

function renderSearchEditor(
    markdown: string,
    props: SearchEditorOverrides = {},
) {
    const onChange = vi.fn()
    const onDirtyChange = vi.fn()
    const view = render(
        <AppThemeProvider>
            <MarkdownEditor
                markdown={markdown}
                onChange={onChange}
                onDirtyChange={onDirtyChange}
                {...props}
            />
        </AppThemeProvider>,
    )

    return { onChange, onDirtyChange, ...view }
}

function selectText(textbox: HTMLTextAreaElement, start: number, end = start) {
    textbox.setSelectionRange(start, end)
    fireEvent.select(textbox)
}

describe('MarkdownEditor local text search', () => {
    afterEach(cleanup)

    it('opens from the shared toolbar search button', () => {
        renderSearchEditor('Find this')

        fireEvent.click(screen.getByRole('button', { name: 'Find text' }))

        expect(screen.getByRole('textbox', { name: 'Find text' })).toHaveFocus()
    })

    it('opens with Ctrl+F without a toolbar and prevents browser find', () => {
        renderSearchEditor('before **Bold** after', { hideToolbar: true })
        const editor = screen.getByRole('textbox') as HTMLTextAreaElement
        selectText(editor, 9, 13)

        const browserEventAllowed = fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })

        expect(browserEventAllowed).toBe(false)
        expect(screen.getByRole('textbox', { name: 'Find text' })).toHaveValue('Bold')
        expect(screen.getByRole('textbox', { name: 'Find text' })).toHaveFocus()
    })

    it('keeps typed search text as a focused draft until Enter submits it', async () => {
        renderSearchEditor('Alpha beta ALPHA')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        selectText(editor, 6)
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })

        fireEvent.change(searchField, { target: { value: 'Alpha' } })

        expect(searchField).toHaveValue('Alpha')
        expect(searchField).toHaveFocus()
        expect(editor.selectionStart).toBe(6)
        expect(editor.selectionEnd).toBe(6)

        fireEvent.keyDown(searchField, { key: 'Enter' })

        await waitFor(() => expect(editor.selectionStart).toBe(11))
        expect(editor.selectionEnd).toBe(16)
    })

    it('submits search from the accessible popup button', async () => {
        renderSearchEditor('before target')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.change(searchField, { target: { value: 'target' } })
        const searchButton = screen.getByRole('button', { name: 'Search' })

        fireEvent.mouseOver(searchButton)
        expect(await screen.findByRole('tooltip')).toHaveTextContent('Search')
        fireEvent.click(searchButton)

        await waitFor(() => expect(editor.selectionStart).toBe(7))
        expect(editor.selectionEnd).toBe(13)
    })

    it('does not search on match-case changes and submits the selected case mode', async () => {
        renderSearchEditor('Alpha ALPHA')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        selectText(editor, 0)
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.change(searchField, { target: { value: 'ALPHA' } })
        const matchCase = screen.getByRole('button', { name: 'Match case' })

        expect(matchCase).toHaveAttribute('aria-pressed', 'false')
        fireEvent.click(matchCase)

        expect(editor.selectionStart).toBe(0)
        expect(editor.selectionEnd).toBe(0)
        expect(matchCase).toHaveAttribute('aria-pressed', 'true')

        fireEvent.keyDown(searchField, { key: 'Enter' })

        await waitFor(() => expect(editor.selectionStart).toBe(6))
        expect(editor.selectionEnd).toBe(11)
    })

    it('leaves editor selection unchanged when an empty term is submitted', () => {
        renderSearchEditor('unchanged')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        selectText(editor, 3)
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })

        fireEvent.keyDown(searchField, { key: 'Enter' })
        fireEvent.click(screen.getByRole('button', { name: 'Search' }))

        expect(editor.selectionStart).toBe(3)
        expect(editor.selectionEnd).toBe(3)
    })

    it('uses submitted term and case mode for F3 despite later draft changes', async () => {
        renderSearchEditor('Alpha alpha Alpha')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.change(searchField, { target: { value: 'Alpha' } })
        fireEvent.click(screen.getByRole('button', { name: 'Match case' }))
        fireEvent.keyDown(searchField, { key: 'Enter' })
        await waitFor(() => expect(editor.selectionEnd).toBe(5))

        fireEvent.change(searchField, { target: { value: 'alpha' } })
        fireEvent.click(screen.getByRole('button', { name: 'Match case' }))
        fireEvent.keyDown(searchField, { key: 'F3' })

        await waitFor(() => expect(editor.selectionStart).toBe(12))
        expect(editor.selectionEnd).toBe(17)

        fireEvent.keyDown(searchField, { key: 'F3' })

        await waitFor(() => expect(editor.selectionStart).toBe(0))
    })

    it('leaves editor selection unchanged when F3 has no valid submission', () => {
        renderSearchEditor('one two one')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        selectText(editor, 4)
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.change(searchField, { target: { value: 'one' } })

        fireEvent.keyDown(searchField, { key: 'F3' })

        expect(editor.selectionStart).toBe(4)
        expect(editor.selectionEnd).toBe(4)
    })

    it('leaves selection and editor state unchanged for a missing term', async () => {
        const { onChange, onDirtyChange } = renderSearchEditor('unchanged')
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        selectText(editor, 3)
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })

        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.change(searchField, { target: { value: 'missing' } })
        fireEvent.keyDown(searchField, { key: 'Enter' })

        await waitFor(() => expect(editor.selectionStart).toBe(3))
        expect(editor).toHaveValue('unchanged')
        expect(onChange).not.toHaveBeenCalled()
        expect(onDirtyChange).not.toHaveBeenCalledWith(true)
    })

    it('does not edit, persist, or add document history while selecting matches', async () => {
        const dataSource = new SearchTestDataSource('one two one')
        const historyStore = new MarkdownDocumentHistoryStore()
        render(
            <AppThemeProvider>
                <MarkdownEditor
                    binding="list-card"
                    dataSource={dataSource}
                    historyStore={historyStore}
                />
            </AppThemeProvider>,
        )
        const editor = screen.getAllByRole('textbox')[0] as HTMLTextAreaElement
        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })

        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.change(searchField, { target: { value: 'one' } })
        fireEvent.keyDown(searchField, { key: 'Enter' })
        await waitFor(() => expect(editor.selectionEnd).toBe(3))

        expect(dataSource.edit).not.toHaveBeenCalled()
        expect(dataSource.commit).not.toHaveBeenCalled()
        expect(historyStore.canUndo).toBe(false)
        expect(historyStore.canRedo).toBe(false)
    })

    it('works in a read-only hidden-toolbar editor and closes with Escape', () => {
        renderSearchEditor('locked text', { hideToolbar: true, readOnly: true })
        const editor = screen.getByRole('textbox')

        fireEvent.keyDown(editor, { ctrlKey: true, key: 'f' })
        const searchField = screen.getByRole('textbox', { name: 'Find text' })
        fireEvent.keyDown(searchField, { key: 'Escape' })

        expect(screen.queryByRole('textbox', { name: 'Find text' })).not.toBeInTheDocument()
        expect(editor).toHaveValue('locked text')
    })

    it('renders popup inside the supplied overlay container', () => {
        const overlayContainer = document.createElement('div')
        document.body.append(overlayContainer)
        renderSearchEditor('content', { overlayContainer })

        fireEvent.click(screen.getByRole('button', { name: 'Find text' }))

        expect(overlayContainer).toContainElement(screen.getByRole('textbox', { name: 'Find text' }))
        overlayContainer.remove()
    })

    it('can opt out and leave Ctrl+F unhandled', () => {
        renderSearchEditor('prompt', { hideToolbar: true, localTextSearch: false })

        const browserEventAllowed = fireEvent.keyDown(screen.getByRole('textbox'), { ctrlKey: true, key: 'f' })

        expect(browserEventAllowed).toBe(true)
        expect(screen.queryByRole('textbox', { name: 'Find text' })).not.toBeInTheDocument()
    })
})

import {
    $createParagraphNode,
    $createRangeSelection,
    $createTextNode,
    $getRoot,
    $getSelection,
    $isRangeSelection,
    $setSelection,
    createEditor,
    type LexicalEditor,
} from 'lexical'
import { describe, expect, it } from 'vitest'
import {
    findMarkdownTextMatch,
    getMarkdownSearchSeed,
    getMarkdownSearchSelectionEnd,
    selectMarkdownTextMatch,
} from './markdown_local_text_search'

function editorWithTextNodes(...texts: string[]) {
    const editor = createEditor()
    editor.update(() => {
        const paragraph = $createParagraphNode()
        const textNodes = texts.map((text, index) => {
            const textNode = $createTextNode(text)
            if (index % 2 === 1) textNode.toggleFormat('bold')
            return textNode
        })
        paragraph.append(...textNodes)
        $getRoot().append(paragraph)
    }, { discrete: true })

    return editor
}

function setTextSelection(editor: LexicalEditor, nodeIndex: number, start: number, end = start) {
    editor.update(() => {
        const node = $getRoot().getAllTextNodes()[nodeIndex]
        const selection = $createRangeSelection()
        selection.anchor.set(node.getKey(), start, 'text')
        selection.focus.set(node.getKey(), end, 'text')
        $setSelection(selection)
    }, { discrete: true })
}

function selectedText(editor: LexicalEditor) {
    return editor.getEditorState().read(() => {
        const selection = $getSelection()
        return $isRangeSelection(selection) ? selection.getTextContent() : ''
    })
}

describe('Markdown local text search', () => {
    it('finds case-insensitive and case-sensitive matches', () => {
        expect(findMarkdownTextMatch('Alpha alpha', 'ALPHA', 0, false)).toEqual({ end: 5, start: 0 })
        expect(findMarkdownTextMatch('Alpha alpha', 'ALPHA', 0, true)).toBeNull()
    })

    it('starts at the supplied offset and wraps once', () => {
        expect(findMarkdownTextMatch('one two one', 'one', 3, false)).toEqual({ end: 11, start: 8 })
        expect(findMarkdownTextMatch('one two one', 'one', 11, false)).toEqual({ end: 3, start: 0 })
    })

    it('returns no match for empty or missing terms', () => {
        expect(findMarkdownTextMatch('content', '', 0, false)).toBeNull()
        expect(findMarkdownTextMatch('content', 'missing', 0, false)).toBeNull()
    })

    it('maps and selects a match spanning adjacent Lexical text nodes', () => {
        const editor = editorWithTextNodes('cross', 'node boundary')

        selectMarkdownTextMatch(editor, 'ssnode', 0, false)

        expect(selectedText(editor)).toBe('ssnode')
    })

    it('reads selected visible text and its document-order end offset', () => {
        const editor = editorWithTextNodes('before ', 'selected', ' after')
        setTextSelection(editor, 1, 0, 8)

        expect(getMarkdownSearchSeed(editor)).toBe('selected')
        expect(getMarkdownSearchSelectionEnd(editor)).toBe(15)
    })

    it('leaves selection unchanged when term has no match', () => {
        const editor = editorWithTextNodes('unchanged')
        setTextSelection(editor, 0, 2, 5)

        selectMarkdownTextMatch(editor, 'missing', 5, false)

        expect(selectedText(editor)).toBe('cha')
    })
})
